syntax:
Template functions and classes:
```c++
template <typename T>
T max(const T& a, const T& b) {
  return (a > b) ? a : b;
}

template <int N>
struct Factorial {
  static const int value = N * Factorial<N - 1>::value;
};

template <> // Partial template specialization
struct Factorial<0> {
  static const int value = 1;
};
```

code_example:
#include <iostream>
#include <type_traits>
template <typename T>
constexpr T max(const T& a, const T& b) { return (a > b) ? a : b; }
template <typename T>
struct IsEven : std::false_type {};
template <typename T>
struct IsEven<T> : std::integral_constant<bool, (std::is_integral_v<T> && (std::is_same_v<std::decay_t<T>, int> || std::is_same_v<std::decay_t<T>, long long>))> {};
int main() {
  std::cout << max(5, 10) << std::endl;  // Calls int version
  std::cout << max(5.5f, 10.1f) << std::endl; // Calls float version
  std::cout << IsEven<int>::value << std::endl; //Compile time evaluation
  std::cout << IsEven<double>::value << std::endl; //Compile time evaluation
  return 0;
}
